import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> modifyFactorize(int n) {
        List<Integer> factors = new ArrayList<Integer>();
        for (int i = 2; i <= n; i++) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        int sum = 0;
        for (Integer x : factors) {
            sum += x;
        }
        factors.add(sum);
        Collections.sort(factors);
        return factors;
    }
}

