def median(l: list, cmp_func: callable):
    def select_pivot(a, b, c):
        return sorted([a, b, c], key=len)[1]

    def partition(l, low, high):
        pivot = select_pivot(l[low], l[(low + high) // 2], l[high])
        pivot_index = l.index(pivot)
        l[low], l[pivot_index] = l[pivot_index], l[low]
        i = low + 1
        j = high
        while True:
            while i < high and cmp_func(l[i], pivot) <= 0:
                i += 1
            while j > low and cmp_func(l[j], pivot) >= 0:
                j -= 1
            if i >= j:
                break
            l[i], l[j] = l[j], l[i]
        l[low], l[j] = l[j], l[low]
        return j

    def select_median(l, pos):
        if len(l) == 1:
            return l[0]

        pivot_index = partition(l, 0, len(l)-1)

        if pos < pivot_index:
            return select_median(l[:pivot_index], pos)
        elif pos > pivot_index:
