import psycopg2

# Configuration
DATABASE_URI = 'postgresql+psycopg2://user:password@localhost:5432/mydatabase'

class Database:
    def __init__(self):
        self.engine = create_engine(DATABASE_URI)
        self.connection = self.engine.connect()
        self.meta = MetaData()
        Session = sessionmaker(bind=self.engine)
        self.session = Session()

    def create(self, table_name, **kwargs):
        table = Table(table_name, self.meta, autoload_with=self.engine)
        try:
            insert_statement = table.insert().values(**kwargs)
            self.connection.execute(insert_statement)
        except SQLAlchemyError as e:
            print(str(e))
            self.session.rollback()
        else:
            self.session.commit()

    def read(self, table_name, **kwargs):
        table = Table(table_name, self.meta, autoload_with=self.engine)
        select_statement = table.select().where(**kwargs)
        result_set = self.connection.execute(select_statement)
        for row in result_set:
            print(row)

    def update(self, table_name, filters, **kwargs)
        table = Table(table_name, self.meta, autoload_with=self.engine)
        try:
            update_statement = table.update().where(**filters).values(**kwargs)
            self.connection.execute(update_statement)
        except SQLAlchemyError as e:
            print(str(e))
            self.session.rollback()
        else:
            self.session.commit()

    def delete(self, table_name, **kwargs):
        table = Table(table_name, self.meta, autoload_with=self.engine)
        try:
            delete_statement = table.delete().where(**kwargs)
            self.connection.execute(delete_statement)
        except SQLAlchemyError as e:
            print(str(e))
            self.session.rollback()
        else:
            self.session.commit()

    def close(self):
        self.session.close()
        self.connection.close()

